-- V-L21 (run O1, lane otkdata): after L21-l1-series-games-corrections.sql, the two per-series games.
-- Read only, in a read-only transaction. Each row is: ok or KO | what | the number found. Never a name of a person, an e-mail or a target of a day.
begin transaction read only;
select case when ok is true then 'ok' else 'KO' end, what, coalesce(got, '-') from (values
  (1, 'One Piece : 72 cibles possibles (73 moins Kyros et Jesus Burgess, plus Boa Hancock)', (select count(*) = 72 from public.character_game_facts where game_id = 'otakudle-one-piece' and can_be_target), (select count(*)::text from public.character_game_facts where game_id = 'otakudle-one-piece' and can_be_target)),
  (2, 'Dragon Ball : 48 cibles possibles', (select count(*) = 48 from public.character_game_facts where game_id = 'otakudle-dragon-ball' and can_be_target), (select count(*)::text from public.character_game_facts where game_id = 'otakudle-dragon-ball' and can_be_target)),
  (3, 'Kyros et Jesus Burgess ne sont plus des cibles, Boa Hancock en est une', (select count(*) = 3 from public.character_game_facts f join public.characters c on c.id = f.character_id where f.game_id = 'otakudle-one-piece' and ((c.slug in ('kyros', 'jesus-burgess') and not f.can_be_target) or (c.slug = 'boa-hancock' and f.can_be_target))), null),
  (4, 'prime : 11 personnages sans prime du Gouvernement Mondial (Aucune prime, valeur 0)', (select count(*) = 11 from public.character_game_facts f join public.characters c on c.id = f.character_id where f.game_id = 'otakudle-one-piece' and f.attrs -> 'bounty' ->> 'l' = 'No bounty' and c.slug in ('monkey-d-garp', 'borsalino', 'issho', 'aramaki', 'koby', 'kin-emon', 'rebecca', 'viola', 'sakazuki', 'smoker', 'tashigi')), null),
  (5, 'mer d''origine : plus aucun "New World" (Grand Line le couvre), Boa Hancock "Calm Belt"', (select count(*) = 0 from public.character_game_facts where game_id = 'otakudle-one-piece' and attrs -> 'sea_of_origin' ->> 'v' = 'New World') and (select count(*) = 1 from public.character_game_facts f join public.characters c on c.id = f.character_id where f.game_id = 'otakudle-one-piece' and c.slug = 'boa-hancock' and f.attrs -> 'sea_of_origin' ->> 'v' = 'Calm Belt'), null),
  (6, 'Dragon Ball : Cell et le Dr Gero Android, Pilaf Monster, Oolong Puar Korin Animal', (select count(*) = 6 from public.character_game_facts f join public.characters c on c.id = f.character_id where f.game_id = 'otakudle-dragon-ball' and ((c.slug in ('cell', 'dr-gero') and f.attrs -> 'race' ->> 'v' = 'Android') or (c.slug = 'emperor-pilaf' and f.attrs -> 'race' ->> 'v' = 'Monster') or (c.slug in ('oolong', 'puar', 'korin') and f.attrs -> 'race' ->> 'v' = 'Animal'))), null),
  (7, 'Dragon Ball : plus de double espace dans une affiliation', (select count(*) = 0 from public.character_game_facts where game_id = 'otakudle-dragon-ball' and attrs -> 'affiliation' ->> 'v' like '%  %'), null),
  (8, 'une cible a toutes les colonnes de son jeu', (select count(*) = 0 from public.character_game_facts f join public.dle_attributes a on a.game_id = f.game_id where f.can_be_target and coalesce(cardinality(public.dle_values(f.attrs -> a.key -> 'v')), 0) = 0), null),
  (9, 'sources : chaque correction (revision) a une adresse et un identifiant de révision', (select count(*) >= 20 from public.entity_sources s where s.entity_type = 'character' and s.field ~ '^(one-piece|dragon-ball)[.]' and s.source_ref ~ '^[0-9]+$' and s.source_url ~ '^https://'), (select count(*)::text from public.entity_sources s where s.entity_type = 'character' and s.field ~ '^(one-piece|dragon-ball)[.]' and s.source_ref ~ '^[0-9]+$'))
) as c(n, what, ok, got) order by n;
rollback;
